const int MOTOR = 9;
const unsigned long RAMP_MS = 2000;
unsigned long start;

void setup() {
  pinMode(MOTOR, OUTPUT);
  start = millis();
}

void loop() {
  unsigned long t = millis() - start;
  if (t < RAMP_MS) {
    analogWrite(MOTOR, t * 255 / RAMP_MS);
  } else {
    analogWrite(MOTOR, 255);
  }
}

